```

LWC:
```javascript
// lwc/contact-list.js
import { LightningElement, track } from 'lwc';
import getContacts from '@salesforce/apex/ContactListController.getContacts';
import editContact from '@salesforce/apex/ContactListController.editContact';

export default class ContactList extends LightningElement {
    @track contacts;

    connectedCallback() {
        this.fetchContacts();
    }

    fetchContacts() {
        const accountId = this.template.querySelector('[data-id="accountId"]').value;
        getContacts({ accountId })
            .then(result => {
                this.contacts = result;
            })
            .catch(error => {
                console.error(error);
            });
    }

    editContact(event) {
        const contactId = event.target.dataset.id;
        editContact({ contactId })
            .then(result => {
                this.fetchContacts();
            })
            .catch(error => {
                console.error(error);
            });
    }
}
```

