Here's a simple Aura and LWC Lightning Component that displays a table of Contact records based on the selected Account. It also includes an Edit button for each contact record.

**Aura Component:**

```html
<aura:component controller="ContactListController">
    <aura:attribute name="contacts" type="List" />
    <aura:attribute name="selectedAccountId" type="String" default=""/>
    <lightning:table data={contacts} keyField="Id" columns="{
        'name': 'Name',
        'email': 'Email',
        'phone': 'Phone'
    }">
        <template for:each={contacts} for:item="contact">
            <td>{contact.Name}</td>
            <td>{contact.Email}</td>
            <td>{contact.Phone}</td>
            <td><button onclick={editContact} value={contact.Id}>Edit</button></td>
        </template>
    </lightning:table>
    <lightning:select aura:id="accountSelect" name="selectedAccountId" onChange={handleAccountChange} />
</aura:component>
```

**Aura Controller:**

```javascript
({ onInit, handleAccountChange, editContact }) => {
    this.onInit = () => {
        // Fetch contacts from server
        const action = component.get("c.getContacts");
        action.setCallback(this, (response) => {
            this.contacts = response.getReturnValue();
        });
        $A.enqueueAction(action);
    };

    this.handleAccountChange = (event) => {
        this.selectedAccountId = event.target.value;
    };

    this.editContact = (event) => {
        const contactId = event.target.value;
        const action = component.get("c.editContact");
        action.setParams({ contactId });
        action.setCallback(this, (response) => {
            // Update contacts in UI
            this.contacts = response.getReturnValue();
        });
        $A.enqueueAction(action);
    };
};
```

