function swapAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];

  for (let i = 0; i < words.length; i++) {
    if (words[i].match(/^adjective$/)) {
      adjectives.push(words[i]);
    }
  }

  if (adjectives.length > 1) {
    const firstAdjective = adjectives[0];
    const lastAdjective = adjectives[adjectives.length - 1];
    adjectives.splice(0, 1, lastAdjective);
    adjectives.splice(adjectives.length - 1, 1, firstAdjective);
  }

  return adjectives.join(" ");
}

const sentence = "Beautiful green trees are in the park";
const result = swapAdjectives(sentence);
