 if (!convertedMessage) {
 return;
 }

 convertedMessage.metaData = { ...(convertedMessage.metaData || {}), chatId: this.chatId };

 this.uwpTextDataBus.next(convertedMessage);
 });
 }

 subscribe(
 channel: string,
 decisionTreeHandler: DecisionTreeDataBus.IActionHandler
 ): DecisionTreeDataBus.IUnsubscribe {
