To achieve this, you can use the following Arduino code:

```cpp
#include <Adafruit_NeoPixel.h>
#define PIN 5
#define NUM_LEDS 60

Adafruit_NeoPixel strip(NUM_LEDS, PIN);
int buttonPin = 2;
int currentLed = 0;
bool buttonState = false;

void setup() {
  strip.begin();
  pinMode(buttonPin, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    buttonState = true;
  } else {
    buttonState = false;
  }

  if (buttonState) {
    currentLed++;
    if (currentLed >= NUM_LEDS) {
      currentLed = 0;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
      int redValue = (i * 255) / NUM_LEDS;
      int greenValue = (i * 255) / NUM_LEDS;
      int blueValue = (i * 255) / NUM_LEDS;

      strip.setPixelColor(i, strip.Color(redValue, greenValue, blueValue));
    }

    strip.show();
  }
}
```

This code uses an Adafruit NeoPixel library to control the LED strip. It also includes a button input to trigger the lighting of the next LED. When the button is pressed, the current LED will increment and the color of each LED will fade with the rainbow colors.

