Here's a C++ program that implements a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int n, a, b;

    // Prompt the user to input the first two integers
    cout << "Enter the first two integers: ";
    getline(cin, input);

    // Parse the input strings into integers
    istringstream iss(input);
    iss >> a >> b;

    // Prompt the user to input the number of sequence elements to generate
    cout << "Enter the number of sequence elements to generate: ";
    cin >> n;

    // Error handling for invalid inputs
    if (a < 0 || b < 0 || n < 0) {
        throw runtime_error("Invalid input. All values must be non-negative.");
    }

    // Generate the Fibonacci sequence
    vector<int> sequence(n);
    sequence[0] = a;
    sequence[1] = b;
    for (int i = 2; i < n; i++) {
        sequence[i] = fibonacci(i, b, a + b);
    }

    // Output the generated sequence
    cout << "Fibonacci sequence:";
    for (int i = 0; i < n; i++) {
        cout << " " << sequence[i];
    }
    cout << endl;

    return 0;
}
```

