Here's a simple implementation of the bubble sort algorithm in C++ to sort the given array of integers in ascending order. This implementation uses a nested loop structure to compare and swap elements, ensuring that the largest element bubbles up to the end of the array on each pass. The function returns the sorted array.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

std::vector<int> bubbleSort(const std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
            }
        }
    }
    return arr;
}

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    std::vector<int> sortedArr = bubbleSort(arr);
    std::cout << "Sorted array: ";
    for (int i = 0; i < sortedArr.size(); ++i) {
        std::cout << sortedArr[i] << " ";
    }
    return 0;
}
```

