    var colors: [String: Int] = [:]
    for user in data {
        for color in user.colorPreferences {
            colors[color] = (colors[color] ?? 0) + 1
        }
    }
    return colors.sorted { $0.value > $1.value }.map { $0.key }
}

func mostReviewedProducts(in data: [UserData]) -> [String] {
    var products: [String: Int] = [:]
    for user in data {
        for product in user.productReviews {
            products[product] = (products[product] ?? 0) + 1
        }
    }
    return products.sorted { $0.value > $1.value }.map { $0.key }
}
