```javascript
const Nest = require('nest');
const TypeOrm = require('typeorm');

const app = Nest.create(Nest.Module({
  imports: [
    TypeOrm.forRoot(),
  ],
  controllers: [],
  providers: [],
}));

app.useGlobalGuards(new ProfessionalAccessPermissionsGuard());

function ProfessionalAccessPermissionsGuard() {
  return async (context, next) => {
    const user = context.req.user;
    if (!user) {
      throw new Error('Unauthorized');
    }

    const permissions = ['permission1', 'permission2'];
    if (!permissions.some(permission => user.roles.includes(permission))) {
      throw new Error('Forbidden');
    }

    await next();
  };
}

module.exports = app;
```

Here's an example of how you can use Google Maps API with Apps Script to find the latitude and longitude of a place and store it in another column:

```javascript
function findLatLng() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var placeName = sheet.getRange("A1").getValue(); // Assuming the place name is in cell A1

  var geocoder = new google.maps.Geocoder();
  geocoder.geocode({ 'address': placeName }, function(results, status) {
    if (status === 'OK') {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      sheet.getRange("B1").setValue(latitude); // Store latitude in cell B1
      sheet.getRange("C1").setValue(longitude); // Store longitude in cell C1
    } else {
      sheet.getRange("D1").setValue("Error: " + status); // Store error message in cell D1
    }
  });
}
```

This script will search for the place name in cell A1 and store its latitude and longitude in cells B1 and C1 respectively. If there's an error, it will store an error message in cell D1.

Make sure to enable the Google Maps API in your Apps Script project by going to "Resources" > "Advanced Google services". Also, make sure to replace `'placeName'` with the actual place name you want to search for.

To achieve this, you can use Google Apps Script to fetch data from a sheet and perform a geocoding search using the Google Maps API. Here's a sample script:

```javascript
function getLatLong() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A1:C10"); // Assuming your data is in columns A to C, rows 1 to 10
  var data = dataRange.getValues();

  for (var i = 1; i < data.length; i++) {
    var placeName = data[i][0]; // Assuming the first column contains place names
    var url = "https://maps.googleapis.com/maps/api/geocode/json?address=" + placeName + "&key=YOUR_API_KEY";

    var response = UrlFetchApp.fetch(url);
    var json = JSON.parse(response);

    if (json.results.length > 0) {
      var latitude = json.results[0].geometry.location.lat;
      var longitude = json.results[0].geometry.location.lng;

      data[i][1] = latitude; // Assuming the second column will contain latitudes
      data[i][2] = longitude; // Assuming the third column will contain longitudes
    } else {
      data[i][1] = "";
      data[i][2] = "";
    }
  }

  sheet.getRange("D1:D" + (data.length + 1)).setValues(data); // Assuming the fourth column will contain latitudes
}
```

Replace `YOUR_API_KEY` with your actual Google Maps API key. This script will loop through the specified range, fetch the latitude and longitude of each place name using the Google Maps API, and store the results in the corresponding columns.

Here's an example Google Apps Script that searches for a place name in a column and stores the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  var dataRange = sheet.getRange("A1:C10"); // Assuming your data is in columns A to C, rows 1 to 10
  var placeName = "New York"; // Replace with the place name you want to search for

  var geocoder = new google.maps.Geocoder();
  geocoder.geocode({ 'address': placeName }, function(results, status) {
    if (status == google.maps.GeocoderStatus.OK) {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      for (var i = 1; i <= dataRange.getNumRows(); i++) {
        var cell = dataRange.getCell(i, 1);
        if (cell.getValue() == placeName) {
          dataRange.getCell(i, 2).setValue(latitude);
          dataRange.getCell(i, 3).setValue(longitude);
          break;
        }
      }
    } else {
      console.log("Geocode was not successful for the following reason: " + status);
    }
  });
}
```

Replace `"New York"` with the place name you want to search for. This script will search for the place name in column A and store the latitude and longitude in columns B and C respectively. You can modify the range and column numbers as needed.

