A JavaScript promise is a way to handle asynchronous tasks, like fetching data from an API or waiting for a user to input something. It's like a container that holds the result of an asynchronous task and allows you to do something with it when it's ready.

Here's a simple example:
```javascript
// This function fetches data from an API and returns a promise
function fetchData() {
  return new Promise((resolve, reject) => {
    // Simulate a network request
    setTimeout(() => {
      resolve('Data fetched!');
    }, 1000);
  });
}

// This code uses the fetchData function and does something with the result
fetchData()
  .then(result => console.log(result))
  .catch(error => console.error(error));
```
In this example, the `fetchData` function returns a promise that resolves with the string "Data fetched!" after one second. The `then` method is used to handle the resolved value, while the `catch` method is used to handle any errors that occur during the asynchronous task.

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an object where the nested key value matches the string key:

```javascript
function getEntriesByKey(obj, key) {
  const keys = key.split(".");
  let result = obj;

  for (const key of keys) {
    if (result[key] !== undefined) {
      result = result[key];
    } else {
      return [];
    }
  }

  return result;
}
```

You can use this function like this:

```javascript
const obj = {
  foo: {
    bar: "baz",
    qux: "quux"
  },
  baz: "quz"
};

const key = "foo.bar";
const entries = getEntriesByKey(obj, key);
console.log(entries); // Output: ["baz"]
```

Here's a JavaScript function that takes a string variable in dot notation and returns all entries in an option where the nested key value matches the string key:

```javascript
function getOptionEntries(option, key) {
  const keys = key.split(".");
  let currentObject = option;

  for (const key of keys) {
    if (!currentObject[key]) {
      return [];
    }
    currentObject = currentObject[key];
  }

  return currentObject;
}

// Example usage
const option = {
  fruit: {
    apple: {
      color: "red",
      quantity: 10
    },
    banana: {
      color: "yellow",
      quantity: 5
    }
  }
};

const key = "fruit.apple.color";
const entries = getOptionEntries(option, key);
console.log(entries); // Output: ["red"]
```

```javascript
function getOptionValues(dotNotatedString, matchKey) {
  const options = {};

  // Split the dot-notated string into an array of keys
  const keys = dotNotatedString.split(".");

  // Iterate through each key and add its corresponding value to the options object
  for (const key of keys) {
    if (!options[key]) {
      options[key] = [];
    }

    const value = matchKey === key ? options[key] : options[key].filter(v => v === matchKey);
    options[key] = value;
  }

  return options;
}
```

