Here's a simple React hook that allows you to convert temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import { useState } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const convertToCelsius = (temp, unit) => {
    if (unit === 'fahrenheit') {
      return (temp - 32) * 5 / 9;
    } else if (unit === 'kelvin') {
      return temp - 273.15;
    }
    return temp;
  };

  const convertToFahrenheit = (temp, unit) => {
    if (unit === 'celsius') {
      return temp * 9 / 5 + 32;
    } else if (unit === 'kelvin') {
      return temp + 273.15;
    }
    return temp;
  };

  const convertToKelvin = (temp, unit) => {
    if (unit === 'celsius') {
      return temp + 273.15;
    } else if (unit === 'fahrenheit') {
      return (temp - 32) * 5 / 9 + 273.15;
    }
    return temp;
  };

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  return { temperature, unit, handleInputChange, handleUnitChange, convertToCelsius, convertToFahrenheit, convertToKelvin };
};

export default useTemperatureConverter;
```

