  { name: 'green apple', position: 9, randomize: false }
];

let shuffledFruits = [];

for (let i = 0; i < fruits.length; i++) {
  const fruit = fruits[i];
  if (fruit.randomize) {
    shuffledFruits.push(fruit);
  } else {
    shuffledFruits.splice(fruit.position - 1, 0, fruit);
  }
}

console.log(shuffledFruits);
```

