Here's a Python script that should help you identify the most common non-silent vowel and consonant combinations in a given text:

```python
import re

def get_non_silent_vowels(text):
    vowels = 'aeiou'
    return [v for v in vowels if v not in 'yw']

def get_non_silent_consonants(text):
    return re.findall(r'\b[^aeiouy]\b', text)

def count_combinations(text):
    vowels = get_non_silent_vowels(text)
    consonants = get_non_silent_consonants(text)
    combinations = []

    for v in vowels:
        for c in consonants:
            combination = f"{v}{c}"
            combinations.append(combination)

    return combinations, len(combinations)

def main():
    text = """Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed non risus. Suspendisse lectus tortor, dignissim sed, adipiscing nec, ultricies sed, dolor. Cras mattis consectetur purus, sed tincidunt magna aliquet non."""

    combinations, total_combinations = count_combinations(text)

    print("Most common non-silent vowel and consonant combinations:")
    for combination, count in sorted(combinations.items(), key=lambda x: x[1], reverse=True)[:10]:
        print(f"{combination}: {count}")

    print(f"Total number of combinations: {total_combinations}")

if __name__ == "__main__":
    main()
```

