To create a script for Unity that displays a visualizer in time with the music, you'll need to use the AudioSource and AudioListener components in Unity. Here's a simple script to get you started:

```csharp
using UnityEngine;

public class MusicVisualizer : MonoBehaviour
{
    public float visualizerScale = 1f;
    public float visualizerSpeed = 1f;

    private AudioSource audioSource;
    private AudioListener audioListener;
    private float currentTime = 0f;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        audioListener = GetComponent<AudioListener>();
    }

    void Update()
    {
        currentTime += Time.deltaTime * visualizerSpeed;
        float amplitude = audioSource.volume * visualizerScale;

        // Adjust the visualizer's position or scale based on the amplitude
        transform.localScale = new Vector3(amplitude, amplitude, amplitude);
    }
}
```

