Here's a simple script for Unity that takes an audio file as input and displays a visualizer in time with the music:

```csharp
using UnityEngine;
using UnityEngine.Audio;

public class AudioVisualizer : MonoBehaviour
{
    public AudioClip audioClip;
    public float visualizerScale = 1f;
    public Color[] colors = new Color[10];

    private AudioSource audioSource;
    private float currentTime = 0f;
    private float visualizerWidth = 0f;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        audioSource.clip = audioClip;
        audioSource.Play();

        visualizerWidth = GetComponent<Renderer>().bounds.size.x * visualizerScale;
    }

    void Update()
    {
        currentTime += Time.deltaTime;

        float amplitude = audioSource.volume * Mathf.Sin(currentTime * 2 * Mathf.PI);
        float visualizerPosition = amplitude * visualizerWidth;

        for (int i = 0; i < colors.Length; i++)
        {
            float colorValue = Mathf.Abs(amplitude) * i / (colors.Length - 1);
            colors[i] = new Color(colorValue, colorValue, colorValue);
        }

        GetComponent<Renderer>().material.color = colors[(int)(visualizerPosition / visualizerWidth) % colors.Length];
    }
}
```

This script plays an audio clip and uses its volume to control the position of a visualizer. The visualizer is a bar that moves horizontally across the screen, with the color changing based on the amplitude of the audio. You can adjust the `visualizerScale` and `colors` variables to customize the appearance of the visualizer.

