def is_prime(n: int) -> bool:
    """Check if the given number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_maximum(numbers: list[int]) -> int:
    """Find the maximum value in the given list."""
    max_value = numbers[0]
    for number in numbers:
        if number > max_value:
            max_value = number
    return max_value

def calculate_average(numbers: list[float]) -> float:
    """Calculate the average value in the given list."""
    total = sum(numbers)
    average = total / len(numbers)
    return average

def validate_email(email: str) -> bool:
    """Validate if the given email address is valid."""
    import re
    pattern = r'^[\w\.-]+@[\w\.-]+\.\w+$'
