    while 'Workflows' in response:
        failed_workflows.extend(response['Workflows'])
        response = client.list_workflows(
            WorkflowStatusFilter='Failed',
            MaxResults=10,
            NextToken=response['NextToken']
        )

    return failed_workflows

def get_workflow_inputs(client, workflow_id):
    response = client.get_workflow_definition(
        WorkflowId=workflow_id
    )

    inputs = {}
    for input_ in response['Definition']['Inputs']:
        inputs[input_['Name']] = input_['Type']

    return inputs

def re_execute_workflow(client, workflow_id, inputs):
    retry_suffix = "_retry"
    new_workflow_name = f"{workflow_id}{retry_suffix}"

    response = client.start_workflow_execution(
        WorkflowId=new_workflow_name,
        Input={
            key: value
            for key, value in inputs.items()
        }
    )

