```typescript
import { ExecutionContext, Injectable } from '@nestjs/common';

@Injectable()
export class EnvDecorator {
  constructor(private readonly ctx: ExecutionContext) {}

  public use(): boolean {
    const env = this.ctx.switchToHttp().getRequest().env;
    return env?.NODE_ENV === 'true';
  }
}
```

Use this decorator in your middleware:

```typescript
import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';
import { EnvDecorator } from './env-decorator';

@Injectable()
export class MyMiddleware implements CanActivate {
  constructor(private readonly envDecorator: EnvDecorator) {}

  canActivate(context: ExecutionContext): boolean {
    return this.envDecorator.use();
  }
}
```

Here's a decorator for Nest.js middleware that checks the `NODE_ENV` variable and calls the next function if it's equal to 'true', but returns false if it's equal to 'false':

```typescript
import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';

@Injectable()
export class EnvMiddleware implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();
    const nodeEnv = process.env.NODE_ENV;

    if (nodeEnv === 'true') {
      return true;
    }

    return false;
  }
}
```

You can use this decorator in your Nest.js controller like this:

```typescript
import { Controller, Get, UseInterceptors } from '@nestjs/common';
import { EnvMiddleware } from './env.middleware';

@Controller('your-controller-path')
export class YourController {
  @Get()
  @UseInterceptors(new EnvMiddleware())
  getData(): any {
    // Your data fetching logic here
  }
}
```

This will ensure that the `getData` method is only executed when the `NODE_ENV` variable is set to 'true'. If it's set to 'false', the method will return false and the request will not be processed further.

```typescript
import { Injectable, CanActivate } from '@nestjs/common';

@Injectable()
export class EnvDecorator implements CanActivate {
  canActivate(context) {
    const env = process.env.NODE_ENV;
    if (env === 'true') {
      return context.switchToHttp().getRequest().serverResponse.status(200).send();
    } else {
      return context.switchToHttp().getRequest().serverResponse.status(403).send();
    }
  }
}
```

