Here's a simple example of a toast notification using React Context:

```jsx
import React, { createContext, useContext } from 'react';

const ToastContext = createContext({
  showToast: () => {},
});

function ToastProvider(props) {
  const [showToast, setShowToast] = React.useState(false);

  function handleClick() {
    setShowToast(true);
  }

  return (
    <ToastContext.Provider value={{ showToast, handleClick }}>
      {props.children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { showToast, handleClick } = useContext(ToastContext);

  return (
    <div>
      <button onClick={handleClick}>Show Toast</button>
      {showToast && <p>Toast is shown!</p>}
    </div>
  );
}

export default function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}
```

In this example, we have a `ToastContext` that provides a `showToast` function and a `handleClick` function to the child components. The `ToastProvider` component wraps around the child components and sets the initial state for the `showToast` variable. The `ToastConsumer` component consumes the `ToastContext` and renders a button that triggers the `handleClick` function when clicked. When the `handleClick` function is called, it sets the `showToast` variable to true, which causes the toast message to be displayed.

To create a simple toast notification using React Context, follow these steps:

1. Create a `ToastContext` file:

```javascript
import React, { createContext, useState } from 'react';

export const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  function addToast(message) {
    setToasts((prevToasts) => [...prevToasts, message]);
  }

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export default ToastProvider;
```

2. Create a `Toast` component:

```javascript
import React from 'react';
import { useContext } from 'react';

const Toast = () => {
  const { toasts } = useContext(ToastContext);

  return (
    <div>
      {toasts.map((toast, index) => (
        <div key={index}>{toast}</div>
      ))}
    </div>
  );
};

export default Toast;
```

3. Use the `ToastProvider` and `Toast` components in your app:

```javascript
import React from 'react';
import ToastProvider from './ToastContext';
import Toast from './Toast';

function App() {
  return (
    <ToastProvider>
      <Toast />
    </ToastProvider>
  );
}

export default App;
```

Now you have a simple toast notification system using React Context. You can use the `addToast` function to add new toasts to the list. The `Toast` component will display all the toasts in the list.

To create a simple toast notification using React Context, follow these steps:

1. Create a `NotificationContext` component:

```javascript
import React from 'react';

const NotificationContext = React.createContext();

function NotificationProvider({ children }) {
  const [notifications, setNotifications] = React.useState([]);

  const addNotification = (notification) => {
    setNotifications((prevNotifications) => [...prevNotifications, notification]);
  };

  return (
    <NotificationContext.Provider value={{ notifications, addNotification }}>
      {children}
    </NotificationContext.Provider>
  );
}

export { NotificationContext, NotificationProvider };
```

2. Create a `Notification` component:

```javascript
import React from 'react';
import { useContext } from 'react';

const Notification = () => {
  const { notifications } = useContext(NotificationContext);

  return (
    <div>
      {notifications.map((notification) => (
        <div key={notification.id}>{notification.message}</div>
      ))}
    </div>
  );
};

export default Notification;
```

3. Use the `NotificationContext` in your application:

```javascript
import React from 'react';
import { NotificationProvider, Notification } from './NotificationContext';

const App = () => {
  return (
    <NotificationProvider>
      <Notification />
      <button onClick={() => addNotification({ id: Date.now(), message: 'New notification' })}>Add notification</button>
    </NotificationProvider>
  );
};

export default App;
```

