```python
import gspread
from typing import Dict

def parse_dict(sheet_key: str, sheet_name: str, row_number: int) -> Dict[str, str]:
    gc_client = gspread.service_account()
    sheet = gc_client.open_by_key(sheet_key).worksheet(sheet_name)

    data = {}
    for i, row in enumerate(sheet.get_all_records()):
        if i == row_number - 1:
            for j, value in enumerate(row):
                data[value.lower()] = row[j+1].value

    return data
```

Here's an example of how you can implement an email input field with TypeScript, React, and the Downshift library. This implementation uses the `useCombobox` hook to create an input field that autocompletes the email as the user types. It calls the `searchEmails` function to retrieve the emails based on what the user types.

```typescript
import { useCombobox } from 'downshift';
import axios from 'axios';

const EmailInputField = () => {
  const [inputValue, setInputValue] = useState('');
  const [emails, setEmails] = useState([]);

  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: emails,
    itemToString: (item) => item.email,
    defaultHighlightedIndex: 0,
  });

  const handleInputChange = (event) => {
    setInputValue(event.target.value);
    searchEmails(event.target.value);
  };

  const handleSelect = (selectedItem) => {
    setSelectedItem(selectedItem);
    setInputValue(selectedItem.email);
  };

  const searchEmails = async (prefix) => {
    try {
      const response = await axios.get(`https://api.example.com/emails`, {
        params: { prefix },
      });
      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} value={inputValue} onChange={handleInputChange} />
      <ul {...getMenuProps()}>
        {isOpen && (
          <li key="no-results">No results found</li>
        )}
        {emails.map((email) => (
          <li key={email.id} onClick={() => handleSelect(email)}>
            {email.name} <span>{email.email}</span>
          </li>
        ))}
      </ul>
    </div>
  );

