import { useCombobox } from 'downshift';

const EmailInputField = () => {
  const [emails, setEmails] = React.useState([]);
  const [selectedEmail, setSelectedEmail] = React.useState('');

  const searchEmails = async (prefix: string) => {
    // Replace this with your actual API call or logic to fetch emails
    const mockEmails = ['john@example.com', 'jane@example.com', 'bob@example.com'];
    const filteredEmails = mockEmails.filter((email) => email.startsWith(prefix));
    setEmails(filteredEmails);
  };

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getComboboxProps,
    highlightedIndex,
    getItemProps,
  } = useCombobox({
    items: emails,
    getItemPredicate: (query, item) => item.startsWith(query),
    onSelect: (item) => setSelectedEmail(item),
    onInputValueChange: searchEmails,
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} />
      <ul {...getMenuProps()}>
        {isOpen &&
          emails.map((email, index) => (
            <li
              key={index}
              {...getItemProps({
                item: email,
                index,
                style: {
                  backgroundColor: highlightedIndex === index ? '#f0f0f0' : 'white',
                },
              })}
            >
              {email}
            </li>
          ))}
      </ul>
    </div>
  );
};

export default EmailInputField;
```

