    const prefix = event.target.value;
    searchEmails(prefix); // Call your searchEmails function with the prefix
  };

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps({ onChange: handleInputChange })} />
      <ul {...getMenuProps()}>
        {isOpen &&
          selectedItem != null &&
          selectedItem.emails.map((email, index) => (
            <li
              {...getItemProps({ key: email.email, index })}
              style={{ backgroundColor: highlightedIndex === index ? '#f0f0f0' : 'white' }}
