To create a socket for chatroom using the provided database schema, you'll need to follow these steps:

1. Create a server-side script (e.g., `server.js`) to handle the socket connections and manage the chatroom data.
2. Create a client-side script (e.g., `client.js`) to connect to the server and send/receive chat messages.

Here's an example of how you can implement these scripts using Node.js and Socket.IO:

Server-side (server.js):

```javascript
const http = require('http');
const express = require('express');
const socketio = require('socket.io');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');

const app = express();
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

mongoose.connect('your_mongodb_connection_string', { useNewUrlParser: true, useUnifiedTopology: true });

const chatroomSchema = new mongoose.Schema({
  id: String,
  userIds: [String],
  messages: [{
    senderId: String,
    message: String,
    timestamp: Date
  }]
});

const Chatroom = mongoose.model('Chatroom', chatroomSchema);

const server = http.createServer(app);
const io = socketio(server);

server.listen(3000, () => {
  console.log('Server listening on port 3000');
});

io.on('connection', (socket) => {
  console.log('User connected');

  socket.on('join', (chatroomId) => {
    const chatroom = Chatroom.findById(chatroomId);
    if (!chatroom) {
      return socket.emit('error', 'Invalid chatroom ID');
    }

    socket.join(chatroomId);
    socket.emit('joined', chatroomId);

    // Update the chatroom with the new user
    Chatroom.updateOne({ _id: chatroomId }, { $push: { userIds: socket.id } })
      .

