			fmt.Println("The sentence contains a double negative.")
		}
	}
}

func containsNegativeWord(word string, negativeWords []string) bool {
	for _, w := range negativeWords {
		if w == word || w == "-" + word {
			return true
		}
	}
	return false
}

func hasNotFollowedByWord(word string, words []string, followingWord string) bool {
	prevIndex := -1
	for i, currWord := range words {
		if prevIndex >= 0 && currWord == followingWord {
			return false
		}
		prevIndex = i
	}
	return true
}
```

