class ManageRegistrationScreen extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      registrations: [],
    };
  }

  checkMNPStatusAPI = async (phoneNo, index) => {
    const headers = new Headers();
    headers.append("Authorization", "Bearer " + user.getAccessToken());
    try {
      const response = await fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers,
        method: "GET",
      });
      const jsonData = await response.json();
      const newRegistrations = [...this.state.registrations];
      newRegistrations[index].mnpStatus = jsonData.status;
      this.setState({ registrations: newRegistrations });
    } catch (error) {
      console.error(error);
    }
  };

