# Define function to check if an SID is present in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory {
    param(
        [string]$sid
    )

    $domain = (Get-ADDomain).Name
    $sidHistory = @()

    # Get all users and groups in the domain
    $users = Get-ADUser -Filter * -Properties SID, SIDHistory | Select-Object -ExpandProperty SID
    $groups = Get-ADGroup -Filter * -Properties SID, SIDHistory | Select-Object -ExpandProperty SID

    # Loop through each user and group
    foreach ($object in $users + $groups) {
        # Check if the SID is present in the SIDHistory of the object
        if ($object.SIDHistory -contains $sid) {
            $sidHistory += $object.SID
        }
    }

    # Return true if the SID is present in the SIDHistory of any user or group in the domain, false otherwise
    return ($sidHistory -ne $null)
}

# Define function to recursively check folders for ACLs with SIDs that occur only in the SIDHistory of any user or group in the domain
