        if (CheckAclForSIDHistory($folder.FullName)) {
            Write-Host "Folder: $folder.FullName has ACLs with SIDs that occur only in the SIDHistory of any user or group in the domain"
        }

        # Recursively check subfolders
        CheckFoldersForACLS($folder.FullName)
    }
}

