# Define function to check if an SID is present in SIDHistory
function CheckSIDInSIDHistory {
    param (
        [string]$sid
    )

    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = "(&(objectClass=user)(objectCategory=person)(!(userAccountControl:1.2.840.113556.1.4.803:=2)))"
    $searcher.SearchScope = "Global"

    foreach ($user in $searcher.FindAll()) {
        $sidHistory = $user.Properties["msDS-SIDHistory"].Value
        if ($sidHistory -eq $sid) {
            return $true
        }
    }

    return $false
}

# Define function to recursively check folder ACLs for SIDs in SIDHistory
function CheckFolderACLsForSIDHistory {
    param (
        [string]$path
    )

    Get-Acl -Path $path | ForEach-Object {
        $accessRules = $_.Access
        foreach ($accessRule in $accessRules) {
            if ($accessRule.IdentityReference -match '^S-1-5-21-') {
                $sid = $accessRule.IdentityReference
                if (CheckSIDInSIDHistory -sid $sid) {
                    Write-Host "SID $sid found in SIDHistory of domain users."
                }
            }
        }
    }

    foreach ($subfolder in (Get-ChildItem -Path $path -Directory)) {
        CheckFolderACLsForSIDHistory -path $subfolder.FullName
    }
}

# Call the function with the root folder path
CheckFolderACLsForSIDHistory -path "C:\YourRootFolderPath"
